INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-10T00:10:32.591292+00:00', 'Full system access. Creates businesses, branches, admins. Sees all reports across all businesses.', 'Super Admin', '64583bc8-f348-4d2d-988c-8681a097fed8', 'true', 'true', 'super_admin', NULL);
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-10T00:10:32.591292+00:00', 'General Manager. Creates/manages branches and managers within assigned business(es). Views all reports within their business(es).', 'Admin', '3f94bd78-f0e3-4bde-acea-04e8cee49a81', 'true', 'true', 'admin', NULL);
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-10T00:10:32.591292+00:00', 'Branch Manager. Manages a single branch. Submits weekly reports. Sees only their own branch data.', 'Manager', 'a9a24d5e-764c-4315-bf60-3f3b2f19090b', 'true', 'true', 'manager', NULL);
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-10T00:10:32.591292+00:00', 'Front-line staff. Logs sales, stock movements, daily figures. Sees only their own data.', 'Sales Person', 'fa31bf7d-beed-4ce0-ab51-d7b6c0e150cc', 'true', 'true', 'sales_person', NULL);
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-13T21:58:21.691393+00:00', 'Floor-level oversight; bridge between Manager and Sales Person', 'Supervisor', '00000000-0000-0000-0000-000000000005', 'true', 'true', 'supervisor', '{"can_edit_sales": false, "can_create_users": false, "can_log_incidents": true, "can_view_team_sales": true}');
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-13T21:58:21.691393+00:00', 'Owns stock accuracy ΓÇö receiving, damages, stock counts ΓÇö separate from the sales person', 'Inventory / Store Officer', '00000000-0000-0000-0000-000000000007', 'true', 'true', 'inventory_officer', '{"can_view_scope": "branch", "can_log_damages": true, "can_record_stock_in": true, "can_update_procurement": true}');
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-13T21:58:21.691393+00:00', 'Logs trips, fuel, maintenance, driver-specific activity for the Transport arm', 'Transport / Fleet Officer', '00000000-0000-0000-0000-000000000008', 'true', 'true', 'transport_officer', '{"can_log_fuel": true, "can_log_trips": true, "can_view_scope": "vehicle", "can_log_maintenance": true}');
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-13T21:58:21.691393+00:00', 'View-only oversight; can be handed to an external accountant/auditor without giving edit rights', 'Auditor', '00000000-0000-0000-0000-000000000009', 'true', 'true', 'auditor', '{"can_edit": false, "can_create": false, "can_delete": false, "can_approve": false, "can_view_scope": "configurable"}');
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-16T22:50:44.556302+00:00', 'Runs farm production and produce handling; sells farm output', 'Farm Operations Officer', '6fab3b11-3108-4145-a4a8-a1f017627a55', 'true', 'true', 'farm_operations_officer', NULL);
INSERT INTO public.roles (created_at, description, display_name, id, is_active, is_system, name, permission_flags) VALUES ('2026-09-13T21:58:21.691393+00:00', 'Reconciles money ΓÇö sales, expenses, pending payments ΓÇö without editing sales records', 'Accountant / Finance Officer', '00000000-0000-0000-0000-000000000006', 'true', 'true', 'accountant', '{"can_edit_sales": false, "can_view_scope": "business", "can_view_financials": true}');
